            current_path = queue.pop(0)
            node = current_path[-1]

            if node in visited:
                continue
            visited.add(node)

            if node == goal:
                path.append(node)
                return path[::-1]  # Reverse the path to get start to end

            if not self.directed and not self.heuristic:
