def find_path(graph, start, goal):
    if start is None or goal is None:
        return None

    # Initialize the sets for forward and backward searches
    forward_search = {start}
    backward_search = {goal}
    forward_parents = {start: None}
    backward_parents = {goal: None}
    forward_distance = {start: 0}
    backward_distance = {goal: 0}

    # Function to get the neighbors of a node
    def get_neighbors(node):
        return graph[node]

    # Function to find the next node to explore
    def next_node(search_set, parents, distances):
        min_distance = float('inf')
        next_node = None
        for node in search_set:
            if distances[node] < min_distance:
                min_distance = distances[node]
                next_node = node
        return next_node

    # Bidirectional search loop
    while forward_search and backward_search:
        # Explore the next node from the forward search
        current_node = next_node(forward_search, forward_parents, forward_distance)
        if current_node in backward_search:
            # Found the path
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = forward_parents[current_node]
            path.reverse()
            return path

        # Explore the next node from the backward search
        current_node = next_node(backward_search, backward_parents, backward_distance)
        if current_node in forward_search:
            # Found the path
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = backward_parents[current_node]
            path.reverse()
            return path

        # Expand the current node
        neighbors = get_neighbors(current_node)
        for neighbor in neighbors:
            if neighbor not in forward_search:
                forward_search.add(neighbor)
                forward_parents[neighbor] = current_node
                forward_distance[neighbor] = forward_distance[current_node] + 1

        for neighbor in get_neighbors(neighbor):
            if neighbor not in backward_search:
                backward_search.add(neighbor)
                backward_parents[neighbor] = current_node
                backward_distance[neighbor] = backward_distance[current_node] + 1

    # If no path is found
    return None

